import { useState } from 'react';


function Square({ value, onSquareClick }) {
  return <button className="square" onClick={onSquareClick}>{value}</button>;
}

async function GetLogin() {
  result = await fetch("http://127.0.0.1:32001/login", {
    method: "POST",
    headers: {
      "Content-Type": "application/json"
    },
    body: JSON.stringify({username: "admin", password: "adminpass"})
  });

  const data = await result.json(); 
  return data;
}


export default function Board() {
  const [squares, setSquares] = useState(Array(9).fill(null));
  const [xIsNext, setXIsNext] = useState(true);
  const [login, setLogin] = useState(GetLogin())

  function GestisciClick(pos) {
    if (squares[pos] || calculateWinner(squares)) {
      return;
    }
    const nextSquares = squares.slice();

    if (xIsNext) {
      nextSquares[pos] = "X";
    } else {
      nextSquares[pos] = "O";
    }
    setSquares(nextSquares);
    setXIsNext(!xIsNext);
  }
  const winner = calculateWinner(squares);
  let status;
  if (winner) {
    status = "Winner: " + winner;
  } else {
    status = "Next player: " + (xIsNext ? "X" : "O");
  }

  return (
    <>
      <div className="status">{status}</div>
      <div className="board-row">
        <Square value={squares[0]} onSquareClick={() => GestisciClick(0)} />
        <Square value={squares[1]} onSquareClick={() => GestisciClick(1)} />
        <Square value={squares[2]} onSquareClick={() => GestisciClick(2)} />
      </div>
      <div className="board-row">
        <Square value={squares[3]} onSquareClick={() => GestisciClick(3)} />
        <Square value={squares[4]} onSquareClick={() => GestisciClick(4)} />
        <Square value={squares[5]} onSquareClick={() => GestisciClick(5)} />
      </div>
      <div className="board-row">
        <Square value={squares[6]} onSquareClick={() => GestisciClick(6)} />
        <Square value={squares[7]} onSquareClick={() => GestisciClick(7)} />
        <Square value={squares[8]} onSquareClick={() => GestisciClick(8)} />
      </div>
    </>
  );
}
function calculateWinner(squares) {
  const lines = [
    [0, 1, 2],
    [3, 4, 5],
    [6, 7, 8],
    [0, 3, 6],
    [1, 4, 7],
    [2, 5, 8],
    [0, 4, 8],
    [2, 4, 6]
  ];
  for (let i = 0; i < lines.length; i++) {
    const [a, b, c] = lines[i];
    if (squares[a] && squares[a] === squares[b] && squares[a] === squares[c]) {
      return squares[a];
    }
  }
  return null;
}
